<script lang="ts">
 import BrandLogo from '$lib/components/BrandLogo.svelte';
 import {onMount} from 'svelte';
 import {goto} from '$app/navigation';
 import type {Snippet} from 'svelte';
 import * as Dropdown from '$lib/components/ui/dropdown-menu';
 import {Button} from '$lib/components/ui/button';
 import {BookOpen,Menu,History,Crown,UserRound,ChevronDown,Clapperboard,LogOut,Search,Compass,RectangleVertical,Users,Bookmark} from '@lucide/svelte';
 let {user,path,signInHref,onSignOut,children}:{user:any;path:string;signInHref:string;onSignOut:()=>void;children:Snippet}=$props();
 let menuButton=$state<HTMLButtonElement>();
 let watchMenu=$state(false);const focusedWatching=$derived(path==='/help'||path.startsWith('/watch/')||path.startsWith('/shorts')||path.startsWith('/settings/'));
 let collapsed=$state(false);let query=$state('');
 const links=[{href:'/discover',label:'Discover',icon:Compass},{href:'/shorts',label:'Shorts',icon:RectangleVertical},{href:'/following',label:'Following',icon:Users},{href:'/library',label:'Saved videos',icon:Bookmark},{href:'/history',label:'Watch history',icon:History},{href:'/help',label:'Help & guide',icon:BookOpen}];
 const isActive=(href:string)=>href==='/discover'?['/','/discover','/search'].includes(path):href==='/shorts'?path.startsWith('/shorts'):path===href;
 onMount(()=>{try{const saved=localStorage.getItem('videoflow.viewer.sidebar');collapsed=saved?saved==='collapsed':window.innerWidth<=1000;}catch{}});
 $effect(()=>{path;watchMenu=false;});
 function closeWatchMenu(restoreFocus=false){watchMenu=false;if(restoreFocus)menuButton?.focus();}
 function dismissMenu(event:KeyboardEvent){if(event.key==='Escape'&&watchMenu){event.preventDefault();closeWatchMenu(true);}}
 function toggle(){if(focusedWatching){watchMenu=!watchMenu;return;}collapsed=!collapsed;try{localStorage.setItem('videoflow.viewer.sidebar',collapsed?'collapsed':'expanded');}catch{}}
</script>
<svelte:window onkeydown={dismissMenu}/>
<div class="cloud-app viewer-shell flex h-dvh min-w-0 flex-col bg-background text-foreground">
 <header class="viewer-header"><div class="viewer-brand"><button bind:this={menuButton} class="viewer-menu" onclick={toggle} aria-label={focusedWatching?(watchMenu?'Close navigation':'Open navigation'):(collapsed?'Expand navigation':'Collapse navigation')} aria-expanded={focusedWatching?watchMenu:!collapsed} aria-controls="viewer-navigation"><Menu class="size-5"/></button><a href="/" aria-label="VideoFlow home"><BrandLogo compact/></a></div>{#if path!=='/search'}<form class="header-search" role="search" onsubmit={event=>{event.preventDefault();void goto(`/search?q=${encodeURIComponent(query.trim())}`);}}><label class="sr-only" for="header-video-search">Search videos</label><input id="header-video-search" type="search" bind:value={query} placeholder="Search videos"/><button type="submit" aria-label="Search"><Search class="size-5"/></button></form>{/if}<a class="viewer-mobile-search" href="/search" aria-label="Search videos"><Search class="size-5"/></a><div class="viewer-account">{#if user}<Dropdown.Root><Dropdown.Trigger class="flex items-center gap-2 rounded-md border border-border px-3 py-2 text-sm hover:bg-accent"><UserRound class="size-4"/><span class="max-w-28 truncate">{user.name || user.handle || 'Your account'}</span><ChevronDown class="size-3.5"/></Dropdown.Trigger><Dropdown.Content align="end"><Dropdown.Label>{user.email}</Dropdown.Label><Dropdown.Item onSelect={()=>void goto(`/channels/${user.handle}`)}>Your public profile</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/settings/profile')}>Edit profile</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/library')}>Saved videos</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/history')}>Watch history</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/help')}>Help & getting started</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/settings/account')}>Account settings</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/settings/security')}>Security</Dropdown.Item><Dropdown.Item onSelect={()=>void goto('/settings/billing')}>Payments</Dropdown.Item><Dropdown.Separator/><Dropdown.Item onSelect={()=>void goto('/studio/dashboard')}><Clapperboard class="size-4"/>Open Studio</Dropdown.Item><Dropdown.Separator/><Dropdown.Item onSelect={onSignOut}><LogOut class="size-4"/>Sign out</Dropdown.Item></Dropdown.Content></Dropdown.Root>{:else}<Button href={signInHref} size="sm">Sign in</Button>{/if}</div></header>
 <div class="viewer-body">{#if focusedWatching&&watchMenu}<button class="watch-menu-dismiss" aria-label="Close navigation" tabindex="-1" onclick={()=>closeWatchMenu(true)}></button>{/if}{#if !focusedWatching||watchMenu}<aside class="viewer-rail" class:watch-overlay={focusedWatching} class:collapsed={!focusedWatching&&collapsed} aria-label="Viewing navigation"><nav id="viewer-navigation" aria-label="Browse videos">{#each links as item,index}{#if index===3}<div class="rail-divider" role="separator"></div>{/if}<a onclick={()=>closeWatchMenu()} href={item.href} title={!focusedWatching&&collapsed?item.label:undefined} aria-label={item.label} aria-current={isActive(item.href)?'page':undefined}><item.icon size={21} strokeWidth={1.7}/>{#if focusedWatching||!collapsed}<span>{item.label}</span>{/if}</a>{/each}<div class="rail-divider" role="separator"></div><a onclick={()=>closeWatchMenu()} href="/premium" title={!focusedWatching&&collapsed?'Premium':undefined} aria-label="Premium" aria-current={path==='/premium'?'page':undefined}><Crown size={21} strokeWidth={1.7}/>{#if focusedWatching||!collapsed}<span>Premium</span>{/if}</a></nav><div class="rail-studio"><a onclick={()=>closeWatchMenu()} href="/studio/dashboard" title={!focusedWatching&&collapsed?'Open Studio':undefined} aria-label="Open Studio"><Clapperboard size={21} strokeWidth={1.7}/>{#if focusedWatching||!collapsed}<span>Open Studio</span>{/if}</a>{#if focusedWatching||!collapsed}<p>Your space to create.</p>{/if}</div></aside>{/if}<div class="viewer-surface">{@render children()}</div></div>
 <nav class="viewer-bottom" aria-label="Mobile viewing navigation"><a href="/discover" aria-current={['/','/discover'].includes(path)?'page':undefined}><Compass class="size-5"/>Discover</a><a href="/shorts" aria-current={path.startsWith('/shorts')?'page':undefined}><RectangleVertical class="size-5"/>Shorts</a><a href="/following" aria-current={path==='/following'?'page':undefined}><Users class="size-5"/>Following</a><a href={user?'/library':signInHref} aria-current={path==='/library'?'page':undefined}><Bookmark class="size-5"/>You</a></nav>
</div>

<style>.watch-menu-dismiss{position:absolute;inset:0;z-index:20;background:rgb(0 0 0 / .35)}.viewer-rail.watch-overlay{position:absolute;top:0;bottom:0;left:0;z-index:30;background:var(--background);box-shadow:6px 0 24px #0005}
.viewer-brand{display:flex;align-items:center;gap:16px;min-width:194px}.viewer-menu{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;flex-shrink:0}.viewer-menu:hover{background:var(--muted)}
.header-search{display:flex;flex:1;max-width:620px;margin:auto;border:1px solid var(--border);border-radius:24px;overflow:hidden;height:42px}.header-search input{min-width:0;width:100%;padding:0 18px;background:var(--background);font-size:14px;outline-offset:-3px}.header-search button{display:grid;place-items:center;width:60px;flex-shrink:0;background:var(--muted);border-left:1px solid var(--border)}
.viewer-body{position:relative;display:flex;flex:1;min-height:0;min-width:0}.viewer-surface{display:flex;flex:1;min-width:0;flex-direction:column;overflow:hidden}.viewer-rail{width:232px;flex-shrink:0;display:flex;flex-direction:column;padding:12px;overflow-y:auto}.viewer-rail a{display:flex;align-items:center;gap:22px;min-height:44px;padding:10px 14px;border-radius:10px;font-size:14px}.viewer-rail a :global(svg){flex-shrink:0}.viewer-rail a:hover{background:var(--muted)}.viewer-rail a[aria-current=page]{background:var(--muted);font-weight:600}.rail-divider{height:1px;background:var(--border);margin:16px 2px}.rail-studio{margin-top:24px}.rail-studio p{font-size:12px;color:var(--muted-foreground);padding:8px 14px}.viewer-rail.collapsed{width:76px;padding-inline:10px}.collapsed a{justify-content:center;min-height:48px;padding:12px 0}.viewer-menu:focus-visible,.viewer-rail a:focus-visible,.header-search button:focus-visible{outline:2px solid var(--ring);outline-offset:2px}.viewer-bottom,.viewer-mobile-search{display:none}
@media(max-width:650px){:global(.viewer-header){display:flex!important;gap:14px!important;min-height:62px;flex-wrap:nowrap!important}.viewer-brand{min-width:0;flex:1}.viewer-menu,.header-search,.viewer-rail,.watch-menu-dismiss{display:none}:global(.viewer-account button>span){max-width:68px}.viewer-mobile-search{display:grid;place-content:center;min-width:44px;min-height:44px}.viewer-bottom{display:grid;grid-template-columns:repeat(4,1fr);flex-shrink:0;border-top:1px solid var(--border);background:var(--background);padding:7px 4px max(7px,env(safe-area-inset-bottom))}.viewer-bottom a{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;min-height:44px;font-size:10px;color:var(--muted-foreground)}.viewer-bottom a[aria-current=page]{color:var(--foreground);font-weight:600}}
</style>
